"use strict";
const fs = require("fs"), path = require("path"), crypto = require("crypto");
const root = path.join(__dirname, "lib/athena");
const esbuild = require(path.join(root, "node_modules/esbuild"));
const hash = file => crypto.createHash("sha256").update(fs.readFileSync(file, "utf8").replace(/\r\n/g, "\n")).digest("hex");
function sources(directory) {
    return fs.readdirSync(directory, { withFileTypes: true }).flatMap(entry => entry.isDirectory() ? sources(path.join(directory, entry.name)) : [path.join(directory, entry.name)]).sort();
}
function inventory() {
    return Object.fromEntries([__filename, path.join(root, "package.json"), path.join(root, "package-lock.json"), path.join(root, "tsconfig.json"), ...sources(path.join(root, "src"))].map(file => [path.relative(__dirname, file).replace(/\\/g, "/"), hash(file)]));
}
function build() {
    fs.mkdirSync(path.join(root, "assets"), { recursive: true });
    fs.mkdirSync(path.join(root, "licenses"), { recursive: true });
    for (const [source, target] of [["minisearch/LICENSE.txt", "minisearch.txt"], ["pdfjs-dist/LICENSE", "pdfjs.txt"]]) fs.copyFileSync(path.join(root, "node_modules", source), path.join(root, "licenses", target));
    const common = { absWorkingDir: root, tsconfig: path.join(root, "tsconfig.json"), bundle: true, target: "es2022", legalComments: "eof" };
    esbuild.buildSync({ ...common, entryPoints: ["src/integration.ts"], outfile: "runtime.cjs", platform: "node", format: "cjs", external: ["obsidian"], banner: { js: "/* Generated by build-athena.js. Edit TypeScript sources, then rebuild. */" } });
    const pdfNotice = fs.readFileSync(path.join(root, "node_modules/pdfjs-dist/build/pdf.mjs"), "utf8").match(/^\/\*\*[\s\S]*?\*\//)[0];
    esbuild.buildSync({ ...common, entryPoints: ["src/knowledge/pdf-worker.ts"], outfile: "assets/pdf-worker.js", platform: "browser", format: "iife", define: { process: "undefined" }, banner: { js: "/* PDF.js 5.4.624 bundled for Athena; see ../licenses/pdfjs.txt. */\n" + pdfNotice } });
    const artifacts = ["lib/athena/runtime.cjs", "lib/athena/assets/pdf-worker.js", "lib/athena/licenses/minisearch.txt", "lib/athena/licenses/pdfjs.txt", "lib/athena/THIRD_PARTY_NOTICES.md"];
    fs.writeFileSync(path.join(root, "build-manifest.json"), JSON.stringify({ version: 1, sources: inventory(), artifacts: Object.fromEntries(artifacts.map(file => [file, hash(path.join(__dirname, file))])) }, null, 2) + "\n");
    console.log("Built Athena runtime and isolated PDF worker.");
}
build();
